// Inbox.js

import { format, isAfter, isSameDay } from 'date-fns';
import {
  addTaskDateBtn,
  addTaskDateBtnText,
  editTaskDateBtn,
  editTaskDateBtnText,
  getSelectedDate,
  getSelectedTime,
  todayDate,
  setCallerDialog,
  resetDateAndTime,
  getCallerDialog,
  prePopulateDateTime,
} from './date-picker.js';

const myTodoList = JSON.parse(localStorage.getItem('TodoList')) || [];

const priorityColors = {
  P1: 'p1',
  P2: 'p2',
  P3: 'p3',
  P4: 'p4',
};

let currentView = 'inbox';
const dialog = document.querySelector('.new-task-dialog');
const priorityButton = document.querySelector('.new-task-priority-button');
const priorityDialog = document.querySelector('.priority-dialog');
const priorityContainer = document.querySelector('.priority-options');

const editTaskDialog = document.querySelector('.edit-task-dialog');
const editTitle = document.querySelector('.edit-title-input');
const editDescription = document.querySelector('.edit-description-input');
const editPriorityButton = document.querySelector('.edit-priority-button');
const prioritySvg = document.querySelector('.priority-svg');
const editPrioritySvg = document.querySelector('.edit-priority-svg');
const saveButton = document.querySelector('.edit-save-task');

let editedDate = null;
let editedTime = null;
let currentlyEditing = null;

const addTaskFromPage = document.querySelector('.new-task');
const taskList = document.querySelector('.task-list');

const titleInput = document.querySelector('.new-task-title-input');
const descriptionInput = document.querySelector('.new-task-description-input');
let setPriority = null;

const form = document.querySelector('.task-form');
const stateDisplayText = document.querySelector('.state-display-text');
stateDisplayText.textContent = 'Inbox';

let selectedTab = null;
const navSection = document.querySelector('.nav-section');
const timePicker = document.querySelector('.time-picker');

const additionalTask = document.querySelector('.additional-task');

// Create a new todo object with the provided values from the input fields and display it
export function newTask() {
  const title = titleInput.value;
  const description = descriptionInput.value;

  const todo = {
    title,
    description,
    section: 'inbox',
    dueDate: getSelectedDate(),
    time: getSelectedTime(),
    priority: setPriority,
    id: crypto.randomUUID(),
  };

  myTodoList.push(todo);
  form.reset();
  resetDateAndTime();
  updateList();
  dialog.close();
}

// Destructure the items from the todo and separate them for display
function createTaskItem(tasks) {
  //  Check in the task list and create a new list for each item there
  for (const task of tasks) {
    const itemList = document.createElement('li'); // Create a list for title
    itemList.dataset.id = task.id; // Assign the id of the task to title
    itemList.classList.add('item-list');

    const checkBox = Object.assign(document.createElement('input'), {
      type: 'checkbox',
      className: 'check-box',
      name: 'check-box',
    });

    // Check if the task has a priority assigned or not to assign the appropriate color.

    if (task.priority !== null) {
      checkBox.classList.add(priorityColors[task.priority]);
    }

    const itemTitle = document.createElement('p');
    itemTitle.classList.add('itemTitle');
    itemTitle.textContent = task.title;

    const titleHolder = document.createElement('div');
    titleHolder.classList.add('titleHolder');
    titleHolder.append(checkBox, itemTitle);

    const itemDescription = document.createElement('p');
    itemDescription.classList.add('itemDescription');
    itemDescription.textContent = task.description;

    const dateDue = document.createElement('p');
    dateDue.classList.add('date-due');

    // Check if the task's time is empty or undefined and set the date content accordingly
    if (task.time === null) {
      dateDue.textContent = task.dueDate
        ? format(new Date(task.dueDate), 'eee, MMM dd, yyyy')
        : '';
    } else {
      dateDue.textContent = task.dueDate
        ? `${format(new Date(task.dueDate), 'eee, MMM dd, yyyy')} ${task.time}`
        : '';
    }

    const separator = document.createElement('div');
    separator.classList.add('separator');

    itemList.append(titleHolder, itemDescription, dateDue, separator);
    taskList.append(itemList);

    /// when checkBox is clicked, delete Item and all it's attribute and update the list
    checkBox.addEventListener('click', () => {
      deleteItem(task.id);
      itemList.remove();
      checkBox.remove();
      taskDisplay();
    });
  }
}

// Show all tasks in the inbox section
export function inboxDisplayList(listing) {
  taskList.replaceChildren(); // Clear the list
  createTaskItem(listing);
  taskDisplay();
}

// Filter the tasks by their date and show only tasks that has dates older than today's date
export function upcomingTab() {
  taskList.replaceChildren();
  const upcoming = [...myTodoList]
    .toSorted((a, b) => new Date(a.dueDate) - new Date(b.dueDate))
    .filter((task) => isAfter(new Date(task.dueDate), new Date()));
  currentView = 'upcoming';
  stateDisplayText.textContent = 'Upcoming';

  const group = {};

  // Group tasks by their dates
  for (const task of upcoming) {
    const date = format(new Date(task.dueDate), 'eee, MMM dd, yyyy');
    group[date] ||= [];
    group[date].push(task);
  }

  // Display the tasks by their dates
  for (const [date, tasks] of Object.entries(group)) {
    const header = document.createElement('p');
    header.classList.add('upcoming-header');
    header.textContent = date;
    taskList.append(header);
    createTaskItem(tasks);
  }

  taskDisplay();
}

// Pick the selected Tab and highlight it for recognition
navSection.addEventListener('click', (event) => {
  const highlightedTab = event.target.closest('.nav-item');
  if (!highlightedTab) return;

  if (selectedTab) {
    selectedTab.classList.remove('selected-tab');
  }

  selectedTab = highlightedTab;
  selectedTab.classList.add('selected-tab');
});

// When the Today Tab is clicked change the tab and show only tasks that are due Today
export function todayTab() {
  const todayList = myTodoList.filter((task) =>
    isSameDay(task.dueDate, new Date()),
  );
  currentView = 'today';
  stateDisplayText.textContent = 'Today';
  inboxDisplayList(todayList);
}

// Default Tab, onclick show all tasks and change to the Inbox Tab
export function inboxTab() {
  currentView = 'inbox';
  stateDisplayText.textContent = 'Inbox';
  inboxDisplayList(myTodoList);
}

export function setSelectedTab(tab) {
  selectedTab = tab;
}

// Every time you delete or update the list of task, update localStorage and load accordingly
function updateList() {
  localStorage.setItem('TodoList', JSON.stringify(myTodoList));

  if (currentView === 'inbox') {
    inboxDisplayList(myTodoList);
  } else if (currentView === 'today') {
    todayTab();
  } else {
    upcomingTab();
  }
}

// Get the item's ID and delete it from the Array and update the localStorage
function deleteItem(id) {
  const index = myTodoList.findIndex((b) => b.id === id);
  myTodoList.splice(index, 1);
  updateList();
}

// If task-list is empty display content from new-task, else display the content from the array
function taskDisplay() {
  if (taskList.childNodes.length === 0 || myTodoList.length === 0) {
    additionalTask.style.display = 'none';
    addTaskFromPage.style.display = 'flex';
  } else {
    addTaskFromPage.style.display = 'none';
    additionalTask.style.display = 'flex';
  }
}

// Cancel task, close the dialog and display what was initially on the screen
export function cancelTask() {
  taskDisplay();
  prioritySvgFillCheck();
  resetDateAndTime();
  dialog.close();
}

// Open the dialog for newTask to be added
export function addTaskFromPageButton() {
  setCallerDialog('add');
  addTaskDateBtn.textContent = addTaskDateBtnText;
  checkDate();
  addTaskFromPage.style.display = 'none';
  priorityButton.textContent = 'Priority';
  setPriority = null;
  emptyPriorityCheck();
  prioritySvgFillCheck();
  dialog.showModal();
}

// Open the dialog for newTask to be added
export function addTaskSideBar() {
  setCallerDialog('add');
  addTaskDateBtn.textContent = addTaskDateBtnText;
  addTaskFromPage.style.display = 'none';
  priorityButton.textContent = 'Priority';
  setPriority = null;
  emptyPriorityCheck();
  prioritySvgFillCheck();
  dialog.showModal();
}

// Check if the task had a priority set during creation, and display that priority, else display the 'Priority' text on the button
function emptyPriorityCheck() {
  if (getCallerDialog() === 'edit') {
    editPriorityButton.textContent = setPriority ?? 'Priority';
  }

  if (getCallerDialog() === 'add') {
    priorityButton.textContent = 'Priority';
  }
}

// Create additional task from the 'Add Task' at the bottom of the task list
function addAdditionalTask() {
  additionalTask.addEventListener('click', () => {
    setCallerDialog('add');
    addTaskFromPageButton();
    priorityButton.textContent = 'Priority';
    prioritySvgFillCheck();
  });
}

// If a task is created in the Today tab, automatically set the date to Today's date
function checkDate() {
  if (!selectedTab) return;
  if (selectedTab.id === 'today-tab') {
    addTaskDateBtn.textContent = 'Today';
    todayDate();
  }
}

// Logic for Editing Tasks
function editTask() {
  // When a task is clicked, get the details of the task
  taskList.addEventListener('click', (event) => {
    const todoItem = event.target.closest('.item-list');
    if (!todoItem) return;
    setCallerDialog('edit');

    // Find the task by the ID
    const editedTask = myTodoList.find(
      (task) => task.id === todoItem.dataset.id,
    );

    // Populate the Dialog with the content that was saved with the task
    currentlyEditing = editedTask;
    editTitle.value = editedTask.title;
    editDescription.value = editedTask.description;
    timePicker.value = editedTask.time ?? '';
    prePopulateDateTime(editedTask.dueDate, editedTask.time);

    setPriority = editedTask.priority;
    editedTime = editedTask.time;
    editedDate = editedTask.dueDate;
    prioritySvgFillCheck();

    // Display the date and time on the Date button or display 'Date'
    const displayedDate = editedTask.dueDate
      ? format(new Date(editedTask.dueDate), 'MMM dd')
      : editTaskDateBtnText;

    // If it has a time assign the time else the time is empty
    const displayedTime = editedTask.time ?? '';
    editTaskDateBtn.textContent = `${displayedDate} ${displayedTime}`.trim();
    emptyPriorityCheck();
    editTaskDialog.showModal();

    // If the content were overflowing the line, wrap them onto the next line to fit the dialog box
    editTitle.style.height = 'auto';
    editTitle.style.height = editTitle.scrollHeight + 'px';
    editDescription.style.height = 'auto';
    editDescription.style.height = editDescription.scrollHeight + 'px';
  });
}

// Set and switch between priorities for tasks
priorityContainer.addEventListener('click', (event) => {
  const priority = event.target.closest('.priority-icon');
  if (!priority) return;

  switch (priority.id) {
    case 'priority-one': {
      setPriority = 'P1';
      priorityButton.textContent = 'P1';
      editPriorityButton.textContent = 'P1';

      break;
    }

    case 'priority-two': {
      setPriority = 'P2';
      priorityButton.textContent = 'P2';
      editPriorityButton.textContent = 'P2';

      break;
    }

    case 'priority-three': {
      setPriority = 'P3';
      priorityButton.textContent = 'P3';
      editPriorityButton.textContent = 'P3';

      break;
    }

    default: {
      setPriority = 'P4';
      priorityButton.textContent = 'P4';
      editPriorityButton.textContent = 'P4';
    }
  }

  prioritySvgFillCheck();
  priorityDialog.close();
});

// Set and switch between the priority colors for tasks
function prioritySvgFillCheck() {
  prioritySvg.classList.remove('p1', 'p2', 'p3', 'p4');
  editPrioritySvg.classList.remove('p1', 'p2', 'p3', 'p4');

  switch (setPriority) {
    case 'P1': {
      prioritySvg.classList.add('p1');
      editPrioritySvg.classList.add('p1');

      break;
    }

    case 'P2': {
      prioritySvg.classList.add('p2');
      editPrioritySvg.classList.add('p2');

      break;
    }

    case 'P3': {
      prioritySvg.classList.add('p3');
      editPrioritySvg.classList.add('p3');

      break;
    }

    case 'P4': {
      prioritySvg.classList.add('p4');
      editPrioritySvg.classList.add('p4');

      break;
    }

    default: {
      prioritySvg.classList.add('priority-svg-default');
      editPrioritySvg.classList.add('priority-svg-default');
    }
  }
}

editPriorityButton.addEventListener('click', () => {
  priorityDialog.showModal();
});

priorityButton.addEventListener('click', () => {
  priorityDialog.showModal();
});

// When the save button is clicked, save the new input details and update the task's details
saveButton.addEventListener('click', (event) => {
  event.preventDefault();
  currentlyEditing.title = editTitle.value;
  currentlyEditing.description = editDescription.value;

  if (getSelectedDate() !== null) {
    editedDate = getSelectedDate();
  }

  if (getSelectedTime() !== null) {
    editedTime = getSelectedTime();
  }

  currentlyEditing.dueDate = editedDate;
  currentlyEditing.time = editedTime;
  currentlyEditing.priority = setPriority;

  updateList();
  resetDateAndTime();
  priorityButton.textContent = 'Priority';
  editPriorityButton.textContent = 'Priority';
  setPriority = null;
  editTaskDialog.close();
});

addAdditionalTask();
editTask();
