// Date-picker.js

import {
  format,
  addMonths,
  subMonths,
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  isBefore,
  isSameDay,
  startOfDay,
  getDay,
} from 'date-fns';

let selectedButton = null;
let currentMonth = new Date();
let selectedDate = null;
let selectedTime = null;

const dateHeader = document.querySelector('.month-displayer');
dateHeader.id = 'date-header';
const weekDaysContainer = document.querySelector('.days-container');
const previousBtn = document.querySelector('.prev-arrow');
const nextBtn = document.querySelector('.next-arrow');
const timePicker = document.querySelector('.time-picker');

export const editTaskDateBtn = document.querySelector('.edit-date-button');
export const editTaskDateBtnText = editTaskDateBtn.textContent;
export const addTaskDateBtn = document.querySelector('.new-task-date-button');
export const dateDialog = document.querySelector('.date-dialog');
export const addTaskDateBtnText = addTaskDateBtn.textContent;
let callerDialog = null;

// Function for dynamically displaying the calendar
function renderCalendar() {
  weekDaysContainer.replaceChildren();

  const firstDay = startOfMonth(currentMonth);
  const lastDay = endOfMonth(currentMonth);
  const weekDay = eachDayOfInterval({ start: firstDay, end: lastDay });
  const startingDay = (getDay(firstDay) + 6) % 7;
  const currentTime = new Date();
  const currentHour = format(currentTime, 'HH:mm');

  for (let i = 0; i < startingDay; i++) {
    const emptySpace = document.createElement('div');
    weekDaysContainer.append(emptySpace);
  }

  dateHeader.textContent = format(currentMonth, 'MMMM yyyy');

  // Check all the days and number them accordingly
  for (const days of weekDay) {
    const dayButton = document.createElement('button');
    dayButton.dataset.date = days.toISOString();
    dayButton.textContent = format(days, 'd');
    weekDaysContainer.append(dayButton);

    // Disable all buttons from previous days
    if (isBefore(days, startOfDay(new Date()))) {
      dayButton.disabled = true;
    }

    // When a button is clicked, remove the classlist for the next click
    dayButton.addEventListener('click', () => {
      if (selectedButton) {
        selectedButton.classList.remove('selected');
      }

      const pickerValue = timePicker.value === '' ? null : timePicker.value;
      selectedButton = dayButton;
      selectedDate = days;

      // If the time Picker has a value and the value is less than the current time,
      // set the time to the current hour and minute if the day is today
      selectedTime =
        isSameDay(selectedDate, currentTime) &&
        pickerValue &&
        pickerValue < currentHour
          ? currentHour
          : pickerValue;

      const displayTime = selectedTime ?? ''; // DisplayTime is equal to selected time or empty

      if (callerDialog === 'edit') {
        editTaskDateBtn.textContent =
          `${format(days, 'eee, MMM dd')} ${displayTime}`.trim();
      } else {
        addTaskDateBtn.textContent =
          `${format(days, 'eee, MMM dd')} ${displayTime}`.trim();
      }

      dayButton.classList.add('selected');
      dateDialog.close();
    });
  }

  if (selectedDate) {
    const buttons = weekDaysContainer.querySelectorAll('button');
    for (const button of buttons) {
      if (
        button.dataset.date &&
        isSameDay(new Date(button.dataset.date), selectedDate)
      ) {
        button.classList.add('selected');
        selectedButton = button;
        break;
      }
    }
  }
}

function previousMonth() {
  currentMonth = subMonths(currentMonth, 1);
  renderCalendar();
}

function nextMonth() {
  currentMonth = addMonths(currentMonth, 1);
  renderCalendar();
}

nextBtn.addEventListener('click', (event) => {
  event.preventDefault();
  nextMonth();
});

previousBtn.addEventListener('click', (event) => {
  event.preventDefault();
  previousMonth();
});

addTaskDateBtn.addEventListener('click', (event) => {
  event.preventDefault();
  currentMonth = new Date();
  renderCalendar();
  dateDialog.showModal();
});

editTaskDateBtn.addEventListener('click', (event) => {
  event.preventDefault();
  renderCalendar();
  dateDialog.showModal();
});

dateDialog.addEventListener('click', (event) => {
  if (event.target !== dateDialog) return;
  if (timePicker.value && !selectedDate) {
    selectedDate = new Date();
  }

  selectedTime = timePicker.value || '';

  const displayTime = selectedTime || '';
  const displayDate = selectedDate
    ? format(selectedDate, 'eee, MMM dd')
    : 'Date';

  const btnText = `${displayDate} ${displayTime}`;

  if (callerDialog === 'edit') {
    editTaskDateBtn.textContent = btnText;
  } else {
    addTaskDateBtn.textContent = btnText;
  }

  dateDialog.close();
});

export function getSelectedDate() {
  return selectedDate;
}

export function getSelectedTime() {
  if (selectedTime !== '') {
    return selectedTime;
  }

  return timePicker.value === '' ? null : timePicker.value;
}

export function todayDate() {
  const today = new Date();
  selectedDate = today;
}

export function setCallerDialog(caller) {
  callerDialog = caller;
}

export function getCallerDialog() {
  return callerDialog;
}

export function resetDateAndTime() {
  selectedDate = null;
  selectedTime = null;
  if (selectedButton) {
    selectedButton.classList.remove('selected');
  }

  selectedButton = null;
  timePicker.value = '';
}

export function prePopulateDateTime(date, time) {
  selectedDate = date ? new Date(date) : null;
  selectedTime = time || null;
  timePicker.value = time || '';

  if (date) {
    currentMonth = new Date(date); // Navigate calendar to the task's month
  }
}

renderCalendar();
