// Inbox.js -- entry point

import './styles.css';
import {
  newTask,
  cancelTask,
  addTaskFromPageButton,
  addTaskSideBar,
  todayTab,
  inboxTab,
  upcomingTab,
  setSelectedTab,
} from './inbox.js';

// Inbox Tab on load-up
inboxTab();

// Highlight Inbox Tab on load up
const inboxTabElement = document.querySelector('.inbox-tab');
inboxTabElement.classList.add('selected-tab');
setSelectedTab(inboxTabElement);

const inboxSection = document.querySelector('.inbox-btn');
inboxSection.addEventListener('click', () => {
  inboxTab();
});

const todaySection = document.querySelector('.today-btn');
todaySection.addEventListener('click', () => {
  todayTab();
});

const upcomingSection = document.querySelector('.upcoming-btn');
upcomingSection.addEventListener('click', () => {
  upcomingTab();
});

const addTask = document.querySelector('.task-form');
addTask.addEventListener('submit', (event) => {
  event.preventDefault();
  newTask();
});

const addButton = document.querySelector('.add-btn');
addButton.addEventListener('click', addTaskSideBar);

const secondTaskBtn = document.querySelector('.add-task-button');
secondTaskBtn.addEventListener('click', addTaskFromPageButton);

const cancelButton = document.querySelector('.cancel-task');
cancelButton.addEventListener('click', cancelTask);

// Expand the height of the text area to accommodate text wrapping
const textAreas = document.querySelectorAll('textarea');
for (const textarea of textAreas) {
  textarea.addEventListener('input', () => {
    textarea.style.height = 'auto';
    textarea.style.height = textarea.scrollHeight + 'px';
  });
}
